from decimal import Decimal
from fractions import Fraction
from typing import Any


def _number(value: Any) -> Fraction:
    """Apply legacy NVL/empty-string numeric coercion without float error."""
    if value is None:
        return Fraction(0)

    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Fraction(0)
        return Fraction(Decimal(value))

    if isinstance(value, Fraction):
        return value

    if isinstance(value, Decimal):
        return Fraction(value)

    if isinstance(value, int):
        return Fraction(value)

    if isinstance(value, float):
        return Fraction(Decimal(str(value)))

    return Fraction(Decimal(str(value)))


def _primary_key(value: Any) -> tuple[int, Any]:
    """Provide deterministic ascending ordering for valid homogeneous keys."""
    if value is None:
        return (0, "")
    if isinstance(value, str):
        return (1, value)
    if isinstance(value, (int, float, Decimal, Fraction)):
        return (2, _number(value))
    return (3, str(value))


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[Any, Any]] = []

    eligible_indices = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG", "") != "Y"
        and account.get("ACCT_TYP", "") == "C"
    ]
    eligible_indices.sort(
        key=lambda index: _primary_key(new_accounts[index].get("ACCT_ID"))
    )

    live_orders = [
        order for order in orders if order.get("DEL_FLG", "") != "Y"
    ]
    live_orders.sort(key=lambda order: _primary_key(order.get("ORD_ID")))

    for index in eligible_indices:
        account = new_accounts[index]
        account_id = account.get("ACCT_ID")
        exposure = Fraction(0)

        for order in live_orders:
            if (
                order.get("ACCT_ID") == account_id
                and order.get("STAT_CD", "") == "I"
            ):
                exposure += _number(order.get("TOT_AMT", ""))

        credit_limit = _number(account.get("CRED_LIMIT", ""))

        if exposure > credit_limit and account.get("CRED_HOLD", "") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if (
            exposure <= credit_limit * Fraction(8, 10)
            and account.get("CRED_HOLD", "") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
